mapper.update:
UPDATE FAQ
SET VIEW_COUNT = VIEW_COUNT + 1
WHERE FAQ_NO = #{faqNo}

mapper.select:
SELECT * FROM ( SELECT F.FAQ_NO, F.QUESTION, F.ANSWER, F.VIEW_COUNT, F.DISPLAY_ORDER, F.CATEGORY_NO, F.STATUS, TO_CHAR(F.CREATED_AT, 'YYYY-MM-DD') AS CREATED_AT, TO_CHAR(F.UPDATED_AT, 'YYYY-MM-DD') AS UPDATED_AT, C.CATEGORY_NAME, C.CATEGORY_CODE, ROW_NUMBER() OVER (ORDER BY F.FAQ_NO DESC) AS RN FROM FAQ F JOIN FAQ_CATEGORY C ON F.CATEGORY_NO = C.CATEGORY_NO WHERE 1=1
AND (F.QUESTION LIKE '%' || #{search} || '%' OR F.ANSWER LIKE '%' || #{search} || '%')
) WHERE RN BETWEEN #{offset} + 1 AND #{offset} + #{limit}

mapper.update:
UPDATE FAQ
SET STATUS = 'D', UPDATED_AT = SYSDATE
WHERE FAQ_NO = #{faqNo}
